INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('1abc1824-2f9a-4f4e-a326-0fb95130e40d','9','atmosfera-caracteristici-climatice','published',1,241,1784631967393,1784631967393);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('1abc1824-2f9a-4f4e-a326-0fb95130e40d','ro','Aproape toate fenomenele meteorologice (nori, ploi, vânt) se petrec în troposferă. Care caracteristică a acestui strat explică cel mai bine acest lucru?','["Aici se află stratul de ozon.","Aici se concentrează cea mai mare parte a vaporilor de apă și circa 90% din masa atmosferei.","Aici temperatura crește cu altitudinea.","Aici se produc aurorele polare."]','Vremea înseamnă nori și precipitații, deci apă. Troposfera adună aproape toți vaporii de apă și cea mai mare parte a aerului, așa că aici se formează norii și cade ploaia.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('45f80c1c-77e9-4b76-a2d2-359d4dc12b28','9','atmosfera-caracteristici-climatice','published',0,242,1784631967393,1784631967393);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('45f80c1c-77e9-4b76-a2d2-359d4dc12b28','ro','Deși vârfurile munților înalți sunt mai aproape de Soare, acolo este mai frig decât la poalele lor. Ce însușire a troposferei explică acest fapt?','["În troposferă temperatura scade cu altitudinea (cu circa 6 °C la fiecare 1000 m).","Vârfurile munților ajung în stratosferă.","Soarele încălzește mai slab vara.","Aerul de la altitudine conține mai mult ozon."]','Apropierea de Soare contează mult mai puțin decât pare; aerul se încălzește de la suprafața Pământului în sus. De aceea, urcând în troposferă, temperatura scade, iar pe vârfuri este frig.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('9c279c2e-e8d1-460c-bfab-7b56c663adf2','9','atmosfera-caracteristici-climatice','published',1,243,1784631967393,1784631967393);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('9c279c2e-e8d1-460c-bfab-7b56c663adf2','ro','Dacă stratul de ozon din stratosferă ar dispărea, care ar fi urmarea directă pentru viața de pe uscat?','["Ar crește cantitatea de oxigen din aer.","Ar ajunge la sol mult mai multe radiații ultraviolete dăunătoare.","Ar dispărea aurorele polare.","Vremea nu s-ar mai schimba niciodată."]','Ozonul este un „scut” împotriva UV. Fără el, radiațiile ultraviolete ar ajunge nefiltrate la suprafață, periculoase pentru plante, animale și oameni.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('37054b13-ff37-4ef0-b04c-f3238621a2ba','9','atmosfera-caracteristici-climatice','published',2,244,1784631967393,1784631967393);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('37054b13-ff37-4ef0-b04c-f3238621a2ba','ro','Undele radio emise de pe Pământ pot fi recepționate la mari distanțe, dincolo de linia orizontului. Ce strat al atmosferei face posibil acest lucru?','["Troposfera, prin norii ei.","Stratosfera, prin stratul de ozon.","Ionosfera, ale cărei straturi ionizate reflectă undele radio înapoi spre sol.","Exosfera, prin centurile Van Allen."]','Ca să ocolească curbura Pământului, unda trebuie „întoarsă” de sus. Straturile ionizate ale ionosferei reflectă undele radio, ajutându-le să ajungă departe.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('f2e6f40e-0946-4e81-b453-0ec118a9331c','9','atmosfera-caracteristici-climatice','published',1,245,1784631967393,1784631967393);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('f2e6f40e-0946-4e81-b453-0ec118a9331c','ro','Un elev crede că, urcând mereu, temperatura aerului scade tot timpul. De ce este greșit acest raționament pentru întreaga atmosferă?','["Pentru că temperatura scade la fel în toate straturile.","Pentru că în stratosferă și în termosferă temperatura crește, nu scade.","Pentru că atmosfera nu are temperatură.","Pentru că troposfera este cel mai cald strat."]','Temperatura urcă și coboară pe straturi: scade în troposferă și mezosferă, dar crește în stratosferă (datorită ozonului) și în termosferă. Deci nu scade continuu.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('3b67ad40-7fe9-474a-87d8-84f6fe9d6e18','9','atmosfera-caracteristici-climatice','published',0,246,1784631967393,1784631967393);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('3b67ad40-7fe9-474a-87d8-84f6fe9d6e18','ro','De ce este atmosfera mai groasă (mai bombată) la Ecuator și mai subțire la poli?','["Din cauza mișcării de rotație a Pământului.","Pentru că la Ecuator sunt mai mulți munți.","Pentru că la poli este mai mult ozon.","Pentru că la Ecuator plouă mai mult."]','Gândește-te ce se întâmplă cu un corp care se rotește repede: se umflă la mijloc. Rotația Pământului „împinge” aerul spre Ecuator, unde atmosfera se bombează.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('88bf4e31-f0e7-4e16-8133-1153fdd61d07','9','atmosfera-caracteristici-climatice','published',0,247,1784631967393,1784631967393);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('88bf4e31-f0e7-4e16-8133-1153fdd61d07','ro','Zăpada proaspătă reflectă puternic lumina Soarelui, iar asfaltul negru o absoarbe aproape în întregime. Ce component al bilanțului radiativ diferă cel mai mult între ele?','["Radiația reflectată (R).","Constanta solară.","Radiația terestră emisă noaptea.","Cantitatea de ozon de deasupra."]','O suprafață albă trimite înapoi multă lumină, una neagră aproape deloc. Deosebirea stă în radiația reflectată (R): mare la zăpadă, mică la asfalt.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('3bfcf4af-0e83-487a-a0e4-df5622ace74e','9','atmosfera-caracteristici-climatice','published',1,248,1784631967393,1784631967393);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('3bfcf4af-0e83-487a-a0e4-df5622ace74e','ro','Doar aproape jumătate din radiația solară ajunge la suprafață. Ce proces reține o parte din radiația ultravioletă în drumul ei prin atmosferă?','["Reflexia norilor.","Absorbția de către stratul de ozon.","Difuzia moleculelor de azot.","Radiația terestră."]','UV-ul este oprit tocmai de „scutul” de ozon. Prin absorbție, ozonul reține o parte din ultraviolete, iar CO₂ și vaporii de apă rețin infraroșii.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('01b3fbff-6d71-4fd2-a363-d114afb81bb4','9','atmosfera-caracteristici-climatice','published',1,249,1784631967393,1784631967393);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('01b3fbff-6d71-4fd2-a363-d114afb81bb4','ro','Alizeele bat constant dinspre tropice spre Ecuator. Ce se întâmplă cu aerul cald ajuns în zona ecuatorială, fapt care menține acolo un „calm”?','["Coboară brusc și formează deșerturi.","Urcă, fiindcă este cald și ușor, lăsând la sol vânturi slabe (calmul ecuatorial).","Îngheață imediat.","Se transformă în curent-jet."]','Aerul cald este mai ușor și tinde să urce. La Ecuator el se ridică, astfel că la suprafață rămân vânturi slabe — de aici „calmul ecuatorial”.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('7c75e639-d123-4c93-8c84-3b8d3f210d4d','9','atmosfera-caracteristici-climatice','published',2,250,1784631967393,1784631967393);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('7c75e639-d123-4c93-8c84-3b8d3f210d4d','ro','Curenții-jet ating viteze de sute de km/h. Unde se manifestă ei, de obicei?','["La nivelul solului, în deșerturi.","În exosferă, printre sateliți.","La limita dintre troposferă și stratosferă, la 9–16 km altitudine.","În mezosferă, la circa 80 km."]','Curenții-jet sunt „râuri” rapide de aer aflate sus, la limita troposferă–stratosferă: jetul polar la 9–12 km, cel tropical la 10–16 km.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('79d2e916-624f-4115-9f31-f4f21cc65c42','9','atmosfera-caracteristici-climatice','published',1,251,1784631967393,1784631967393);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('79d2e916-624f-4115-9f31-f4f21cc65c42','ro','De ce scade temperatura medie anuală de la Ecuator spre poli?','["Pentru că la poli atmosfera conține mai mult CO₂.","Pentru că la Ecuator razele Soarelui cad aproape vertical, iar spre poli tot mai oblic.","Pentru că polii sunt mai aproape de Soare.","Pentru că la Ecuator bat vânturi mai reci."]','Aceeași cantitate de raze încălzește mai puternic când cade drept și mai slab când cade oblic (se împrăștie pe o suprafață mai mare). De aceea la Ecuator e cald, iar spre poli tot mai frig.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('033c5b75-c393-4240-9b20-08b1d5370f4d','9','atmosfera-caracteristici-climatice','published',0,252,1784631967393,1784631967393);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('033c5b75-c393-4240-9b20-08b1d5370f4d','ro','Pe hartă, izotermele au trasee mai netede deasupra oceanelor decât deasupra continentelor. Ce însușire a apei explică acest lucru?','["Apa se încălzește și se răcește mai greu decât uscatul, temperând variațiile de temperatură.","Apa nu are deloc temperatură.","Oceanele sunt mereu mai calde decât uscatul.","Deasupra oceanelor nu există izoterme."]','Apa este un „rezervor” termic: se încălzește și se răcește lent. Fiindcă atenuează extremele, temperaturile de deasupra oceanelor variază lin, iar izotermele sunt mai netede.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('52944bd7-a26b-4a8b-b288-5e3d1da600f9','9','atmosfera-caracteristici-climatice','published',1,253,1784631967393,1784631967393);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('52944bd7-a26b-4a8b-b288-5e3d1da600f9','ro','Ce trebuie să se întâmple cu aerul umed pentru ca vaporii de apă să formeze nori și apoi precipitații?','["Să se încălzească puternic.","Să se răcească, astfel încât vaporii să se condenseze sau să înghețe.","Să coboare spre sol și să se usuce.","Să piardă tot oxigenul."]','Aerul cald ține vaporii; răcit, nu-i mai poate ține. Prin răcire, vaporii se condensează (sau îngheață) și formează norii din care cad precipitațiile.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('fd0b9470-c892-4ccb-ad24-2970b3c33b68','9','atmosfera-caracteristici-climatice','published',2,254,1784631967393,1784631967393);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('fd0b9470-c892-4ccb-ad24-2970b3c33b68','ro','Pe versantul unui munte expus vânturilor dinspre mare plouă mult, iar dincolo de creastă rămâne sec. Ce tip de precipitații explică ploaia de pe versantul expus?','["Precipitații frontale, prin întâlnirea a două fronturi.","Precipitații convective, prin încălzirea solului.","Precipitații orografice: aerul urcă pe munte, se răcește și se condensează.","Precipitații provocate de curenții-jet."]','Muntele „forțează” aerul să urce. Urcând, aerul umed se răcește și lasă ploaia pe versantul expus (orografice), iar dincolo coboară uscat — de aici zona secetoasă.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('84adb7fc-83ce-4377-bfc9-9acff68ccde2','9','atmosfera-caracteristici-climatice','published',2,255,1784631967393,1784631967393);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('84adb7fc-83ce-4377-bfc9-9acff68ccde2','ro','Care tip de nor, dezvoltat mult pe verticală, aduce cele mai abundente averse, adesea cu descărcări electrice?','["Cirrus.","Stratus.","Cumulonimbus.","Altostratus."]','Cu cât norul este mai înalt și mai gros pe verticală, cu atât are mai multă apă. Cumulonimbusul, uriaș pe verticală, dă cele mai mari averse, adesea cu fulgere.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('0e7b82bd-0598-4f5e-90fb-86592fb20ded','9','atmosfera-caracteristici-climatice','published',1,256,1784631967393,1784631967393);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('0e7b82bd-0598-4f5e-90fb-86592fb20ded','ro','Vrem să comparăm câtă ploaie cade în diferite regiuni ale Globului, de la deșertul Atacama la zonele musonice. Ce fel de hartă folosim?','["Harta izotermelor.","Harta izohietelor (linii care unesc puncte cu aceeași cantitate de precipitații).","Harta izobarelor.","Harta curenților-jet."]','Pentru precipitații folosim „izohietele”, nu izotermele (care arată temperatura). Ele unesc punctele cu aceeași cantitate de precipitații și scot în evidență contrastul deșert–zonă musonică.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('9ed75212-1049-4d94-9e63-229f024ccf52','9','atmosfera-caracteristici-climatice','published',1,257,1784631967393,1784631967393);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('9ed75212-1049-4d94-9e63-229f024ccf52','ro','Musonul de vară din Asia aduce ploi bogate, iar cel de iarnă este uscat. De ce musonul de vară este umed?','["Pentru că bate dinspre uscatul continental, cald și uscat.","Pentru că bate dinspre ocean spre uscat, aducând aer încărcat cu vapori de apă.","Pentru că vine din spațiul cosmic.","Pentru că iarna oceanul este mai cald."]','Umezeala vine de la apă. Vara, musonul bate dinspre Oceanul Indian spre uscat, cărând aer plin de vapori — de aceea plouă; iarna sensul se inversează, iar aerul este uscat.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('bd137ffe-0b3d-4752-864f-81bd3d3ab880','9','atmosfera-caracteristici-climatice','published',0,258,1784631967393,1784631967393);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('bd137ffe-0b3d-4752-864f-81bd3d3ab880','ro','Pe litoral, ziua briza bate dinspre mare spre uscat. Ce diferență de încălzire dintre uscat și apă explică sensul brizei de zi?','["Uscatul se încălzește mai repede decât apa; aerul urcă de pe uscat, iar dinspre mare vine aer mai rece.","Apa se încălzește mai repede decât uscatul.","Marea este mereu mai caldă ziua.","Vântul depinde doar de fazele Lunii."]','Ziua, uscatul se încălzește mai repede; aerul de deasupra lui urcă, iar locul îi este luat de aerul mai rece dinspre mare. Așa se naște briza de zi, dinspre apă spre uscat.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('336516bb-50fd-49f3-842c-f6e9bf215d80','9','atmosfera-caracteristici-climatice','published',1,259,1784631967393,1784631967393);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('336516bb-50fd-49f3-842c-f6e9bf215d80','ro','Foehnul este un vânt cald și uscat care coboară pe versanții adăpostiți ai munților, la începutul primăverii. De ce este considerat uneori periculos?','["Pentru că aduce ninsori abundente.","Pentru că topește brusc zăpada, putând declanșa inundații.","Pentru că îngheață râurile.","Pentru că formează stratul de ozon."]','Fiind cald și uscat, foehnul topește rapid zăpada de pe versanți. Apa rezultată dintr-odată poate umfla râurile și provoca inundații.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('5cc0c9f3-3553-42a5-834b-e3216c348362','9','atmosfera-caracteristici-climatice','published',2,260,1784631967393,1784631967393);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('5cc0c9f3-3553-42a5-834b-e3216c348362','ro','Un curent oceanic cald care ajunge la un țărm îi îmblânzește iernile. La ce categorie de factori ai climei se încadrează curenții oceanici?','["Factori radiativi.","Factori dinamici (vânturile).","Factori fizico-geografici (caracteristicile suprafeței terestre).","Elemente climatice."]','Curenții țin de felul suprafeței terestre (apă, uscat, relief) care influențează clima — adică de factorii fizico-geografici, alături de raportul uscat–apă, relief și vegetație.');
